Cook’s Distance — Code

expr_diag &lt;- expr |&gt;
  mutate(
    cooks_d = cooks.distance(lm_expr_raw),
    leverage = hatvalues(lm_expr_raw),
    std_resid = rstandard(lm_expr_raw)
  )

# Flag observations with Cook's D &gt; 4/n (common threshold)
threshold &lt;- 4 / nrow(expr)

expr_diag |&gt;
  filter(cooks_d &gt; threshold) |&gt;
  select(sample_id, bmp4_expression, sox9_expression, std_resid, leverage, cooks_d) |&gt;
  arrange(desc(cooks_d)) |&gt;
  kable(digits = 4)

ANOVA as Linear Model Code

# Fit linear model
iris_lm &lt;- lm(Sepal.Length ~ Species, data = iris)

# Tidy output with broom
tidy(iris_lm) |&gt;
  kable(digits = 4, caption = "ANOVA as Linear Model: Coefficients")

# ANOVA table
anova(iris_lm) |&gt;
  tidy() |&gt;
  kable(digits = 4, caption = "ANOVA Table")
